/**
 * נתוני דוחות יועצות — מוצפן AES-256-GCM
 * לפענוח נדרש PIN
 */

var COUNSELOR_REPORTS_ENCRYPTED = "";
var COUNSELOR_REPORTS = null;


/**
 * פענוח נתוני דוחות יועצות
 * @param {string} pin - קוד PIN
 * @returns {Promise<boolean>} האם הפענוח הצליח
 */
async function decryptCounselorReports(pin) {
  try {
    var raw = atob(COUNSELOR_REPORTS_ENCRYPTED);
    var bytes = new Uint8Array(raw.length);
    for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);

    var salt = bytes.slice(0, 21);
    var nonce = bytes.slice(21, 33);
    var tag = bytes.slice(33, 49);
    var ciphertext = bytes.slice(49);

    var enc = new TextEncoder();
    var keyMaterial = await crypto.subtle.importKey('raw', enc.encode(pin), 'PBKDF2', false, ['deriveKey']);
    var key = await crypto.subtle.deriveKey(
      {name: 'PBKDF2', salt: salt, iterations: 100000, hash: 'SHA-256'},
      keyMaterial,
      {name: 'AES-GCM', length: 256},
      false,
      ['decrypt']
    );

    var combined = new Uint8Array(ciphertext.length + tag.length);
    combined.set(ciphertext);
    combined.set(tag, ciphertext.length);

    var decrypted = await crypto.subtle.decrypt(
      {name: 'AES-GCM', iv: nonce},
      key,
      combined
    );

    var text = new TextDecoder().decode(decrypted);
    COUNSELOR_REPORTS = JSON.parse(text);
    return true;
  } catch (e) {
    console.error('Decryption failed:', e);
    return false;
  }
}

/**
 * חיפוש דוח יועצת לפי שם תלמיד
 */
function findCounselorReport(firstName, lastName) {
  if (!COUNSELOR_REPORTS || !firstName || !lastName) return null;

  var fn = firstName.trim();
  var ln = lastName.trim();
  var fnParts = fn.split(/\s+/);
  var lnParts = ln.split(/\s+/);

  var best = null;
  var bestScore = 0;

  for (var i = 0; i < COUNSELOR_REPORTS.length; i++) {
    var r = COUNSELOR_REPORTS[i];
    var rname = r.name.trim();
    var rparts = rname.split(/\s+/);

    if (rname === ln + ' ' + fn || rname === fn + ' ' + ln) return r;

    var score = 0;
    for (var j = 0; j < rparts.length; j++) {
      for (var k = 0; k < fnParts.length; k++) {
        if (rparts[j] === fnParts[k]) score += 3;
      }
      for (var k = 0; k < lnParts.length; k++) {
        if (rparts[j] === lnParts[k]) score += 3;
      }
    }
    var hasFirst = fnParts.some(function(fp) { return rparts.indexOf(fp) !== -1; });
    var hasLast = lnParts.some(function(lp) { return rparts.indexOf(lp) !== -1; });
    if (hasFirst && hasLast) score += 5;

    if (score > bestScore) { bestScore = score; best = r; }
  }

  return bestScore >= 8 ? best : null;
}
